  .description('create a new project')
  // 为create命令添加一个可选项-f或--force，用于在目标目录已存在时强制覆盖
  .option('-f, --force', 'overwrite target directory if iy exist')
  // 定义create命令的动作，调用create函数并传入名称和选项参数
  .action(async (name, options) => {
    create(name, options)
  })

